const items = $input.all();
const tickets = items.map((item, i) => {
  const d = item.json;
  return `[${i+1}] Subject: ${d.Subject || d.subject || d.Title || ''} | Description: ${d.Description || d.description || d.Body || ''} | Category: ${d.Category || d.category || 'N/A'}`;
}).join('\n');
return [{ json: { ticketSummary: tickets, ticketCount: items.length } }];

const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { faq_entries: [{ question: 'Parse error', answer: aiResponse, category: 'N/A', frequency: 'N/A' }] };
}
const faqEntries = parsed.faq_entries || [];
return faqEntries.map(faq => ({
  json: {
    date: new Date().toISOString().split('T')[0],
    question: faq.question,
    answer: faq.answer,
    category: faq.category || '',
    frequency: faq.frequency || '',
    relatedTickets: faq.related_ticket_count || 0
  }
}));
